"""Accuracy verification: Diaphora 3.5 DB exported by IDA vs. r2diaphora.

Exports ``C:\\Windows\\System32\\calc.exe`` twice:

* ``calc_ida.sqlite`` - generated by running the **vendored, unmodified**
  Diaphora 3.5 exporter inside IDA (`idat.exe -A -S` on
  ``tests/ida_headless_export.py``).
* ``calc_r2.sqlite`` - generated by ``r2diaphora`` (radare2 + r2ghidra).

It then compares schema, function coverage and every decompiler-independent
metric, and finally runs the Diaphora 3.5 diffing engine across both databases.

Run with::

    python -m pytest tests/compare_calc_dbs.py -v -s
"""

import os
import re
import sqlite3
import subprocess
import sys

import pytest

REPO_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
if REPO_ROOT not in sys.path:
    sys.path.insert(0, REPO_ROOT)

from r2diaphora.diaphora_r2 import compare_dbs, generate_db_for_file  # noqa: E402

CALC = r"C:\Windows\System32\calc.exe"
IDA_DIR = r"C:\Program Files\IDA Professional 9.5"
IDAT = os.path.join(IDA_DIR, "idat.exe")
IDA_EXPORT_SCRIPT = os.path.join(REPO_ROOT, "tests", "ida_headless_export.py")
IDA_EXPORT_TIMEOUT = 900

pytestmark = pytest.mark.skipif(
    not os.path.exists(CALC) or not os.path.exists(IDAT),
    reason="calc.exe or idat.exe is not available",
)

# Columns that must be identical between the two exports for the same binary:
# they depend only on disassembly/CFG, never on the decompiler or on IDA's
# internal analysis state (``function_flags`` records SP_READY/PROLOG_OK
# bookkeeping, ``assembly``/``pseudocode*`` are text of different engines).
EXACT_METRIC_COLUMNS = [
    "nodes",
    "edges",
    "indegree",
    "outdegree",
    "size",
    "instructions",
    "cyclomatic_complexity",
    "primes_value",
    "mnemonics",
    "mnemonics_spp",
    "strongly_connected",
    "strongly_connected_spp",
    "loops",
    "tarjan_topological_sort",
    "md_index",
    "bytes_hash",
    "bytes_sum",
    "function_hash",
    "switches",
    "constants",
    "constants_count",
]

# Columns where exact parity is bounded by an IDA-only signal.  IDA emits
# data xrefs for accesses into *named struct-typed* stack slots (e.g.
# ``StartupInfo+4`` or ``EVENT_DESCRIPTOR`` members); radare2 has no
# equivalent frame analysis, so KGH's FEATURE_DATA_REFS factor differs on a
# few functions.  Every other KGH input is verified identical above.
BOUNDED_DIFF_COLUMNS = {"kgh_hash": 6}


def _connect(db_path):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def _functions_by_ea(db_path):
    with _connect(db_path) as conn:
        rows = conn.execute("select * from functions").fetchall()
    return {int(row["address"]): dict(row) for row in rows}


def _schema_objects(db_path):
    with _connect(db_path) as conn:
        rows = conn.execute(
            "select type, name, sql from sqlite_master "
            "where type in ('table', 'index') order by type, name"
        ).fetchall()
    return {
        (row["type"], row["name"]): re.sub(r"\s+", " ", row["sql"] or "").strip()
        for row in rows
    }


def export_ida_db(out_db, workdir, binary=CALC):
    """Run the vendored exporter inside IDA in batch mode."""
    log_path = os.path.join(workdir, "ida_export.log")
    idb_path = os.path.join(
        workdir, os.path.splitext(os.path.basename(binary))[0] + ".i64"
    )
    env = dict(os.environ)
    env.update(
        {
            "R2DIA_UPSTREAM": os.path.join(REPO_ROOT, "r2diaphora", "upstream"),
            "R2DIA_SITEPKG": os.path.join(
                os.path.expanduser("~"),
                "AppData",
                "Roaming",
                "Python",
                f"Python{sys.version_info.major}{sys.version_info.minor}",
                "site-packages",
            ),
            "R2DIA_OUT": out_db,
            "R2DIA_DECOMP": "1",
        }
    )
    cmd = [
        IDAT,
        "-A",
        f"-L{log_path}",
        f"-o{idb_path}",
        f'-S"{IDA_EXPORT_SCRIPT}"',
        binary,
    ]
    proc = subprocess.run(
        cmd,
        cwd=workdir,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=IDA_EXPORT_TIMEOUT,
    )
    if proc.returncode != 0 or not os.path.isfile(out_db):
        tail = ""
        if os.path.isfile(log_path):
            with open(log_path, "r", errors="replace") as stream:
                tail = stream.read()[-4000:]
        raise RuntimeError(
            f"IDA export failed (rc={proc.returncode}):\n"
            f"{proc.stdout.decode('utf-8', 'replace')[-2000:]}\n{tail}"
        )
    return out_db


@pytest.fixture(scope="module")
def diaphora_dbs(tmp_path_factory):
    workdir = str(tmp_path_factory.mktemp("calc_dbs"))
    ida_db = export_ida_db(os.path.join(workdir, "calc_ida.sqlite"), workdir)
    r2_db = generate_db_for_file(
        CALC,
        out_db=os.path.join(workdir, "calc_r2.sqlite"),
        override_if_existing=True,
        use_decompiler=True,
        backend="sqlite",
    )
    return ida_db, r2_db


def test_schema_parity(diaphora_dbs):
    ida_db, r2_db = diaphora_dbs
    ida_schema = _schema_objects(ida_db)
    r2_schema = _schema_objects(r2_db)

    assert set(ida_schema) == set(r2_schema), (
        f"only in IDA: {sorted(set(ida_schema) - set(r2_schema))}\n"
        f"only in r2: {sorted(set(r2_schema) - set(ida_schema))}"
    )
    differences = {
        key: (ida_schema[key], r2_schema[key])
        for key in ida_schema
        if ida_schema[key] != r2_schema[key]
    }
    assert not differences, f"schema differences: {differences}"

    with _connect(r2_db) as conn:
        version = conn.execute("select value from version").fetchone()["value"]
    assert version == "3.4"


def test_program_metadata_parity(diaphora_dbs):
    ida_db, r2_db = diaphora_dbs
    with _connect(ida_db) as conn:
        ida_prog = dict(conn.execute("select * from program").fetchone())
    with _connect(r2_db) as conn:
        r2_prog = dict(conn.execute("select * from program").fetchone())

    assert ida_prog["md5sum"] == r2_prog["md5sum"]
    # IDA >=9 reports "pc64" (older versions reported "metapc64").
    assert ida_prog["processor"] == r2_prog["processor"]
    assert r2_prog["processor"] in ("pc64", "metapc64")


def test_function_coverage_and_metrics(diaphora_dbs, capsys):
    ida_db, r2_db = diaphora_dbs
    ida_funcs = _functions_by_ea(ida_db)
    r2_funcs = _functions_by_ea(r2_db)

    shared = sorted(set(ida_funcs) & set(r2_funcs))
    only_ida = sorted(set(ida_funcs) - set(r2_funcs))
    only_r2 = sorted(set(r2_funcs) - set(ida_funcs))
    print(
        f"\nfunctions: ida={len(ida_funcs)} r2={len(r2_funcs)} "
        f"shared={len(shared)} only_ida={len(only_ida)} only_r2={len(only_r2)}"
    )
    print("only in IDA:", [hex(ea) for ea in only_ida])
    print("only in r2 :", [hex(ea) for ea in only_r2])

    # Recall against the IDA reference: nearly every exported IDA function
    # must also exist in the r2 export.  (IDA's FLIRT signatures additionally
    # tag some CRT stubs FUNC_LIB — entry0/__GSHandlerCheck*/__security_check_
    # cookie — which r2 has no equivalent for, so the r2 side legitimately
    # keeps a few extra functions.)
    recall = len(shared) / max(1, len(ida_funcs))
    assert recall >= 0.9, f"only {recall:.0%} of IDA functions present in r2"

    for column in EXACT_METRIC_COLUMNS + list(BOUNDED_DIFF_COLUMNS):
        mismatches = [
            (hex(ea), ida_funcs[ea][column], r2_funcs[ea][column])
            for ea in shared
            if ida_funcs[ea][column] != r2_funcs[ea][column]
        ]
        if mismatches:
            print(f"  {column}: {len(mismatches)} mismatch(es)")
            for ea, ida_v, r2_v in mismatches[:5]:
                print(f"    {ea}: ida={ida_v!r} r2={r2_v!r}")
        allowed = BOUNDED_DIFF_COLUMNS.get(column, 0)
        assert (
            len(mismatches) <= allowed
        ), f"{column}: {len(mismatches)}/{len(shared)} mismatches"


def test_cross_diff_matches(diaphora_dbs, capsys):
    ida_db, r2_db = diaphora_dbs
    matches = compare_dbs(ida_db, r2_db, backend="sqlite")
    ida_funcs = _functions_by_ea(ida_db)
    r2_funcs = _functions_by_ea(r2_db)
    shared = set(ida_funcs) & set(r2_funcs)

    best = [m for m in matches if m["type"] == "best"]
    partial = [m for m in matches if m["type"] == "partial"]
    unreliable = [m for m in matches if m["type"] == "unreliable"]
    print(
        f"\nchoosers: best={len(best)} partial={len(partial)} "
        f"unreliable={len(unreliable)} (shared functions: {len(shared)})"
    )

    matched_eas = {int(m["address"], 16) for m in matches}
    coverage = len(shared & matched_eas) / max(1, len(shared))
    assert coverage >= 0.9, f"only {coverage:.0%} of shared functions matched"

    # Same binary on both sides: every match must pair the same address and
    # be (near-)identical.
    wrong_pairs = [m for m in matches if m["address"] != m["address2"]]
    assert not wrong_pairs, f"matches pairing different addresses: {wrong_pairs}"
    low_ratio = [m for m in matches if float(m["ratio"]) < 0.9]
    assert not low_ratio, f"unexpected low-ratio matches: {low_ratio}"


if __name__ == "__main__":
    sys.exit(pytest.main([__file__, "-v", "-s"]))
